// This api.js file is generated by Claude AI

// This file's only job: talk to the AniList API and hand back data.
// It does NOT touch the page (no document.querySelector, no HTML).
// That keeps it reusable by both Jen's browse page and Reyan's shelf page.

// 1. The address we send requests to. AniList has just ONE address
//    for everything; the "query" we send decides what data we get back.
const ANILIST_URL = "https://graphql.anilist.co";

// 2. The query. GraphQL is a way of asking "give me exactly these fields".
//    The $something parts are placeholders (variables) we fill in later.
//    Anything not listed here will NOT come back, so add fields you need.
const QUERY = `
  query ($page: Int, $perPage: Int, $search: String, $country: CountryCode, $status: MediaStatus, $genre: String) {
    Page(page: $page, perPage: $perPage) {
      pageInfo {
        currentPage
        hasNextPage
      }
      media(type: MANGA, search: $search, countryOfOrigin: $country, status: $status, genre: $genre, isAdult: false) {
        id
        title {
          romaji
          english
        }
        coverImage {
          large
        }
        averageScore
        chapters
        status
        countryOfOrigin
        genres
      }
    }
  }
`;

// 3. The function the rest of the app will call.
//    "export" lets other files import it.
//    "async" means it uses await inside and returns a Promise.
//    The { ... } = {} part lets you pass only the options you care about,
//    e.g. fetchManga({ search: "solo leveling" }) or fetchManga().
export async function fetchManga({
  page = 1,
  perPage = 20,
  search,
  country,
  status,
  genre,
} = {}) {
  // 4. Send the request. fetch() returns a Promise, and "await" pauses
  //    this function until the server answers (the page doesn't freeze).
  //    GraphQL APIs use POST, with the query and variables in the body.
  const response = await fetch(ANILIST_URL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json",
    },
    body: JSON.stringify({
      query: QUERY,
      variables: { page, perPage, search, country, status, genre },
    }),
  });

  // 5. Check the server said OK. fetch() does NOT throw on a 404 or 500;
  //    it only throws if the network itself is down. So we check manually.
  //    "throw" makes this function fail, and the code that called it can
  //    catch the error and show an error message to the user (required state!).
  if (!response.ok) {
    throw new Error(`AniList request failed (HTTP ${response.status})`);
  }

  // 6. Turn the response text into a JavaScript object. This is async too.
  const json = await response.json();

  // 7. GraphQL can reply with a good HTTP status but still include errors
  //    in the body, so check for that as well.
  if (json.errors) {
    throw new Error(json.errors[0].message);
  }

  // 8. Return just the part the app needs:
  //    { pageInfo: { currentPage, hasNextPage }, media: [ ...series ] }
  return json.data.Page;
}
